<?php
if (!in_array(parse_url($_SERVER['REQUEST_URI'], PHP_URL_PATH), ['/', '/index.php'], true)) { http_response_code(404); exit('Not found.'); }
require dirname(__DIR__).'/app/bootstrap.php';initWeb();
$page=(string)($_GET['page']??'home');$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try {
  if(!hash_equals($_SESSION['csrf'],(string)($_POST['csrf']??''))){http_response_code(403);throw new DomainException('Your form has expired. Refresh and try again.');}
  $action=(string)($_POST['action']??'');
  if($action==='book'){
   if(!empty($_POST['website']))throw new DomainException('Unable to accept this submission.');
   $id=book($_POST);$_SESSION['confirmation']=$id;redirect('/?page=confirmation');
  } elseif($action==='login'){
   $ip=hash('sha256',$_SERVER['REMOTE_ADDR']??'local');$attempt=query('SELECT * FROM attempts WHERE ip_hash=?',[$ip])->fetch();
   if($attempt && $attempt['failures']>=5 && time()-(int)$attempt['last_at']<900)throw new DomainException('Too many attempts. Please try again in 15 minutes.');
   if(!password_verify((string)($_POST['password']??''),(string)query('SELECT password_hash FROM admins LIMIT 1')->fetchColumn())){
    query('INSERT INTO attempts(ip_hash,failures,last_at) VALUES(?,1,?) ON CONFLICT(ip_hash) DO UPDATE SET failures=CASE WHEN last_at < ? THEN 1 ELSE failures+1 END,last_at=?',[$ip,time(),time()-900,time()]);throw new DomainException('The password was not recognized.');
   }
   query('DELETE FROM attempts WHERE ip_hash=?',[$ip]);session_regenerate_id(true);$_SESSION['admin']=true;redirect('/?page=admin');
  } elseif($action==='logout'){session_destroy();redirect('/');
  } elseif($action==='contact'){
   $name=trim((string)($_POST['name']??''));$email=trim((string)($_POST['email']??''));$body=trim((string)($_POST['message']??''));
   if(!$name||strlen($name)>100||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>200||!$body||strlen($body)>2000)throw new DomainException('Complete your name, valid email and message (up to 2,000 characters).');
   query('INSERT INTO messages(name,email,body,created_at) VALUES(?,?,?,?)',[$name,$email,$body,date('c')]);$notice='Your message is saved in the demo inbox. No email was sent.';
  } elseif(in_array($action,['availability','edit'],true)){
   requireAdmin();
   if($action==='availability'){
    query('UPDATE slots SET available=CASE available WHEN 1 THEN 0 ELSE 1 END WHERE id=? AND NOT EXISTS(SELECT 1 FROM appointments WHERE slot_id=slots.id)',[(int)($_POST['slot_id']??0)]);$notice='Availability updated. Booked times remain reserved.';
   } else {
    $data=validateCustomer($_POST);$id=(int)($_POST['id']??0);$slot=(int)($_POST['slot_id']??0);$old=query('SELECT slot_id FROM appointments WHERE id=?',[$id])->fetchColumn();
    if(!$old)throw new DomainException('Appointment not found.');
    db()->beginTransaction();
    try{
     if($slot!==(int)$old){
      if(query('UPDATE slots SET available=0 WHERE id=? AND available=1 AND starts_at>?',[$slot,date('Y-m-d H:i:s')])->rowCount()!==1)throw new DomainException('Choose an available appointment time.');
      query('UPDATE slots SET available=1 WHERE id=?',[$old]);
     }
     query('UPDATE appointments SET slot_id=?,name=?,email=?,address=?,city=?,state=?,zip=?,service=?,extras=? WHERE id=?',[$slot,...array_values($data),$id]);db()->commit();redirect('/?page=admin');
    }catch(Throwable $err){db()->rollBack();throw $err;}
   }
  }
 }catch(DomainException $err){$error=$err->getMessage();if(http_response_code()<400)http_response_code(422);}catch(Throwable $err){error_log($err->getMessage());http_response_code(500);$error='Something went wrong. Please try again.';}
}
if(in_array($page,['admin','edit','availability','inbox'],true))requireAdmin();
function field(string $key,string $label,array $values=[],string $type='text',int $max=200): void {
 echo '<label>'.e($label).'<input name="'.e($key).'" type="'.e($type).'" maxlength="'.$max.'" required value="'.e($_POST[$key]??$values[$key]??'').'"></label>';
}
function customerFields(array $data=[]):void {
 echo '<div class="form-grid">';field('name','Your name',$data,'text',100);field('email','Email address',$data,'email');field('address','Street address',$data);field('city','City',$data,'text',100);field('state','State · two letters',$data,'text',2);field('zip','ZIP code',$data,'text',10);echo '</div><label>Haircare service<select name="service" required>';
 foreach(SERVICES as $name=>$price)echo '<option '.(($data['service']??$_POST['service']??'')===$name?'selected':'').' value="'.e($name).'">'.e($name).' · $'.number_format($price,2).'</option>';
 echo '</select></label><fieldset><legend>A little extra care</legend>';
 foreach(['Shampoo','Style','Bangs, neck & beard trim'] as $extra)echo '<label class="check"><input type="checkbox" name="extras[]" value="'.e($extra).'" '.(str_contains($data['extras']??'', $extra)?'checked':'').'>'.e($extra).' · $'.number_format(SERVICES[$extra],2).'</label>';
 echo '</fieldset>';
}
